const xrmTextNodes = new Map();
const xrmTranslatedAttributes = new Map();
function initStaticTranslation() { captureStaticTranslations(); }
function captureStaticTranslations() {
  const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);
  while(walker.nextNode()) {
    const node=walker.currentNode, parent=node.parentElement;
    if (!parent || parent.closest("#devices-container,#mesh-satellites-list,.nat-list,script,style,textarea,pre")) continue;
    if (!xrmTextNodes.has(node) && XRM_STATIC_TRANSLATIONS[node.nodeValue.trim()]) xrmTextNodes.set(node,node.nodeValue);
  }
  for (const element of document.querySelectorAll("[placeholder],[title],[aria-label]")) {
    if (element.closest("#devices-container,#mesh-satellites-list,.nat-list")) continue;
    let attrs=xrmTranslatedAttributes.get(element);
    for (const attr of ["placeholder","title","aria-label"]) {
      const value=element.getAttribute(attr);
      if (value && XRM_STATIC_TRANSLATIONS[value] && !attrs?.has(attr)) {
        if (!attrs) { attrs=new Map(); xrmTranslatedAttributes.set(element,attrs); }
        attrs.set(attr,value);
      }
    }
  }
}
function applyStaticTranslation() {
  captureStaticTranslations(); document.documentElement.lang=state.lang;
  for(const [node,original] of xrmTextNodes) {
    if(!node.isConnected) continue;
    const key=original.trim(), translated=state.lang === "en" ? XRM_STATIC_TRANSLATIONS[key] : key;
    node.nodeValue=original.replace(key,translated || key);
  }
  for (const [element,attrs] of xrmTranslatedAttributes) {
    if (!element.isConnected) continue;
    for (const [attr,original] of attrs) element.setAttribute(attr,state.lang === "en" ? XRM_STATIC_TRANSLATIONS[original] : original);
  }
  const backupStatus=document.getElementById("backup-file-status");
  if (backupStatus) backupStatus.textContent=backupStatus.dataset.filename ? (state.lang === "en" ? "Loaded: " : "Wczytano: ")+backupStatus.dataset.filename : (state.lang === "en" ? "No JSON backup loaded." : "Nie wczytano kopii JSON.");
}

